DO $migration$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.update_event_details(uuid,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'''name'', trim(t->>''name''), ''price_cents'', (t->>''price_cents'')::int));','''name'', trim(t->>''name''), ''price_cents'', (t->>''price_cents'')::int, ''image_path'', nullif(t->>''image_path'','''')));'); IF definition NOT LIKE '%''image_path''%' THEN RAISE EXCEPTION 'addon_update_pattern_missing'; END IF; EXECUTE definition; END $migration$;
CREATE OR REPLACE FUNCTION public.validate_addon_images() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb; p text; previous jsonb; eventid uuid; candidate jsonb; BEGIN IF TG_TABLE_NAME='events' THEN previous:=CASE WHEN TG_OP='UPDATE' THEN OLD.addons ELSE '[]'::jsonb END; eventid:=NEW.id; candidate:=NEW.addons; IF TG_OP='UPDATE' AND NEW.addons IS NOT DISTINCT FROM OLD.addons THEN RETURN NEW; END IF; ELSE previous:=CASE WHEN TG_OP='UPDATE' THEN coalesce(OLD.snapshot->'details'->'addons','[]'::jsonb) ELSE '[]'::jsonb END; eventid:=NEW.event_id; candidate:=coalesce(NEW.snapshot->'details'->'addons','[]'::jsonb); END IF; FOR a IN SELECT * FROM jsonb_array_elements(candidate) LOOP p:=nullif(a->>'image_path',''); IF p IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(previous) x WHERE x->>'image_path'=p) AND NOT EXISTS(SELECT 1 FROM public.events e,jsonb_array_elements(e.addons) x WHERE e.id=eventid AND public.can_manage_event(eventid) AND x->>'image_path'=p) AND NOT EXISTS(SELECT 1 FROM public.event_builder_drafts d,jsonb_array_elements(coalesce(d.snapshot->'details'->'addons','[]'::jsonb)) x WHERE d.event_id=eventid AND public.can_manage_event(eventid) AND x->>'image_path'=p) THEN IF auth.uid() IS NULL OR p !~ ('^'||auth.uid()::text||'/addon-[a-f0-9-]+[.]webp$') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='media' AND name=p) THEN RAISE EXCEPTION 'invalid_addon_image'; END IF; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_event_addon_images BEFORE INSERT OR UPDATE OF addons ON public.events FOR EACH ROW EXECUTE FUNCTION public.validate_addon_images();
CREATE TRIGGER validate_draft_addon_images BEFORE INSERT OR UPDATE OF snapshot ON public.event_builder_drafts FOR EACH ROW EXECUTE FUNCTION public.validate_addon_images();
COMMENT ON COLUMN public.events.addons IS 'Optional image_path references private uploader-owned media; guest images are resolved by event-bound server signing, never raw paths.';